package io.github.diodeme.ji.extension;

import java.util.concurrent.CompletionStage;

/** Ordered Tool interception seam for audit and validation without transport-specific execution paths. */
public interface ToolInterceptor {
    default CompletionStage<Void> before(ToolInvocation invocation) {
        return java.util.concurrent.CompletableFuture.completedFuture(null);
    }

    default CompletionStage<Void> after(ToolInvocation invocation, ToolCompletion completion) {
        return java.util.concurrent.CompletableFuture.completedFuture(null);
    }

    record ToolInvocation(ToolExecutionPolicy.Context context, String operationId, long operationRevision) {
        public ToolInvocation {
            if (context == null || operationId == null || operationId.isBlank() || operationRevision < 0) {
                throw new IllegalArgumentException("invalid tool invocation");
            }
        }
    }

    record ToolCompletion(String operationId, long operationRevision, Status status) {
        public ToolCompletion {
            if (operationId == null || operationId.isBlank() || operationRevision < 0 || status == null) {
                throw new IllegalArgumentException("invalid tool completion");
            }
        }
    }

    enum Status { SUCCEEDED, DENIED, CANCELLED, FAILED, STALE }
}
